(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,87803,e=>{"use strict";var i=e.i(43476),l=e.i(11337);function s(e){let s={li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,l.useMDXComponents)(),...e.components},{AnketaCollapse:r,AnketaGroup:c,AnketaList:d,AnketaPoint:h,AnketaProse:j,Whisper:x}=s;return r||n("AnketaCollapse",!0),c||n("AnketaGroup",!0),d||n("AnketaList",!0),h||n("AnketaPoint",!0),j||n("AnketaProse",!0),x||n("Whisper",!0),(0,i.jsxs)(c,{children:[(0,i.jsx)(r,{title:"Общая информация",defaultOpen:!0,children:(0,i.jsxs)(d,{children:[(0,i.jsxs)(h,{title:"Имя персонажа [русс|англ]",children:[(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Релестия Люксевиар / Relestia Luxeviar"})," (урождённая Анна Мария фон Вернау)"]}),(0,i.jsxs)(s.ul,{children:["\n",(0,i.jsx)(s.li,{children:"«Рели» / «Релли» — простое сокращение имени, как у Марии — Маша, прямое и приятное в своей прямоте; «р» может быть картавой, растянутой. Обращаются так к ней обычно хорошие знакомые, друзья, откровенно близкие люди, а также её сикигами: Прыг-скок и Крумэ. С сикигами Филимоновной коленкор несколько иной;"}),"\n",(0,i.jsx)(s.li,{children:"«Релюша» и «Релечка» — видоизменённые кадавры изначального имени под нафталиновым воздействием старушки-аристократки Филимоновны, ревностно любящей уменьшительно-ласкательные наименования всего и вся, а в особенности — предметов и людей, которые ей полюбились. Слегка пошловато, в стиле Чичикова, но такова старая школа, сколь бы сильно она ни капала на мозг самой Релестии. И всё-таки в этих прозвищах есть бабушкины теплота и уют, словно в банке закрученных на зиму солёных огурцов."}),"\n"]})]}),(0,i.jsx)(h,{title:"Возраст",children:(0,i.jsxs)(s.ul,{children:["\n",(0,i.jsx)(s.li,{children:"прожитый на Земле: 30 лет."}),"\n",(0,i.jsx)(s.li,{children:"дата рождения: 20 мая 1605."}),"\n",(0,i.jsx)(s.li,{children:"смерти: 14 октября 1635."}),"\n",(0,i.jsx)(s.li,{children:"прожила в Энкраже: 383 года."}),"\n"]})}),(0,i.jsx)(h,{title:"Пол",children:(0,i.jsx)(s.p,{children:"Женский."})}),(0,i.jsx)(h,{title:"Раса",children:(0,i.jsx)(s.p,{children:"Оммёдзи."})})]})}),(0,i.jsxs)(r,{title:"Психологический профиль",children:[(0,i.jsx)(r,{title:"Характер",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(s.p,{children:"Была в ней какая-то особой породы угодливость, как если бы в её захудало-провинциальный ресторанчик, забегаловку, в которой коротают свои сочтённые деньки всякие синяки да пьянчужки, наведался известный столичный ревизор и принялся бы всё ревизировать; и она бы ему и так, и сяк: и чего б ещё вам, ваша милость, не хотите ли чаю, а к чему вообще чай — может, по винишку, а к винишку — какой стейк говяжий, разве нет, а? И она бы и крутилась, и вертелась, и лизоблюдству её, изощрённому, всепроникающему, подлизывающемуся длинным-предлинным языком, шершавым, как у коровы, не было бы предела."}),(0,i.jsx)(s.p,{children:"В неё встроено, вклинено, впаяно чинопочитание, и, хотя в душе она может плеваться и презирать грешника, которому хочет угодить, тщедушная, лицемерная душонка не позволит в полной мере шелохнуться мощной магии, которой она владеет, и будет она глядеть на тех, кто выше её на пару ступенек, как верный дворовой пёсик — снизу вверх. И только тогда она может встрепенуться, воспротивиться своей ублажающей властителей мира сего натуре, если тот, кому она особенно верна, — тот, на кого она наиболее по-щенячьи смотрит и кому то и дело заглядывает в рот, — только если такая фигура, которая в её иерархически устроенной голове занимает пьедестал, укажет ей, на кого надо наброситься, кого надо разорвать на части, — только тогда она, несмотря ни на какие различия в возрасте, чине и силе, бросится в атаку отчаянно, будто бешеная."}),(0,i.jsx)(s.p,{children:"А к тем, кто ниже неё, кто слабее, она относится по-повелительски, подавляюще: как большая тёмная туча, она надвигается на ничего не подозревающие невинные облака-овечки, мирно пасущиеся на синем небосводе, — и изводит она их, понукает ими, готовая каждому показать, где его место, чтобы знали, что они — глупая, безмозглая челядь; и каждого глупца, который своим бараньим взглядом бессмысленно тупил книги по чародействам, — а особенно она не любила чужую глупость и чужое невежество, но своих, конечно, в упор никогда не замечала, — каждого готова была сгноить."}),(0,i.jsx)(s.p,{children:"Она не позволяет слабым пререкаться, демонстрировать характер, свой богатый внутренний мир и тонкую душевную организацию. Хотя она неплохо обучена манерам, хотя она дама и прочее, прочее, Релестия со стоическим спокойствием высморкается в надежды, переживания и всяческие пожелания нижестоящих, как в носовой платок, — как, собственно, и полагается благородной даме, готовой поухаживать за собой в любой момент времени, но в первую очередь — поухаживать за собственным моральным состоянием, поскольку нытьё слизняков под каблуками вызывает у неё головную боль. Но такое происходит не сразу и не всегда. Иначе бы все младшие по званию от неё за километр шарахались и прятались по норам. Она может быть и с теми, кто заведомо слабее неё, кто ей кажется настоящими опарышами, — она может быть с ними учтительно-вежливой, заискивающей, даже слащавой. Любя втираться в доверие, узнавать различные подробности жизни человека, она служит тому ложным маяком — сведущая в мире магии и в обществе оммёдзи, Релестия ведёт его по тому пути, который видится ей правильным, нужным или забавным. И уже потом, когда человек ей хотя бы частично доверился, она с большим удовольствием проявляет злое менторство: садизм, обманы, психологическое давление. И если человек её приятно удивил, приглянулся, Релестия может напрямую предложить своё покровительство — со всеми вытекающими минусами и плюсами. Ведь, несмотря на её требовательность и любовь к истязаниям, она действительно способна научить очень многому."}),(0,i.jsx)(s.p,{children:"При этом же стоит учитывать, что, когда Релестия лебезит пред сильными мира сего, на первый план выходит, как бы это ни было удивительно, именно сила: и не суть важно, магическая ли, физическая ли, паранормальная ли — главное, чтобы тот, перед кем её лоб покрывается нервозно-истеричной испариной, поперёк горла встаёт ком, а тело самоходом уже готово распространиться в бесконечных лакейско-прихлебательских движениях: раскланяться, сделать реверанс и прочая, прочая, прочая, — был по-настоящему силён и могущественен в самом животном понимании этих слов. Титулы, конечно, важны, всяческие должности, чины, регалии, но скорее второстепенны: они вытекают из могущества настоящего, подлинного, и только если Релестия почует, что король-то голый, что персона, увешанная орденами с ног до головы, чьи погоны уходят в бесконечность, — на самом деле ряженая и никакого отношения по факту силы к своему положению не имеет, то такая персона сразу же упадёт по пирамиде взаимоотношений в самый низ и уже не реабилитируется для Релестии. И к таким у неё отношение даже хуже, чем к просто слабакам: ряженых она всегда желает умышленно растоптать, раздавить, стереть с лица земли как недостойных."}),(0,i.jsx)(s.p,{children:"Цепляясь всеми силами за строгую и чёткую иерархию, желая всё ранжировать и сортировать в парадигме «сильный — менее сильный — слабый», Релестия в немалой степени устала от этого, ловя себя время от времени на мысли, что с давних лет живёт как-то автоматически-механически: много учёбы, зубрёжки, познаний, но учение ради учения её мало интересовало — оно скорее было и остаётся мостиком, который позволяет ей достигать того, что в самом деле угодно её душе: приключений, экспедиций; всё это возвращает её обратно в детство, в ту беззаботную мечтательность, которой она обладает и сейчас. Но мир взрослых, мир строгих правил, большой политики и бесконечной иерархичности вынуждает раболепствовать перед теми, кто стоит выше, и, хотя о собственной ущербности она предпочитает не думать, трудно не согласиться, что, вымещая гнев на нижестоящих, кошмаря их почём зря, она старается компенсировать собственную беспросветную зажатость внутри этой системы. И именно поэтому, чтобы не пребывать в долгой, как вечность, апатии от необходимости перманентно соответствовать устоям общества, постоянно учиться, познавать новое — но не из любви к открытию новых горизонтов, а из осточертевшего «надо», — она старается участвовать в гораздо более автономной и полевой деятельности Центра климатогностики, где есть то, чем она по-настоящему горит: экспедиции, опасные и необычные, места, где можно умереть. И именно тогда она чувствует, как пустынно-безжизненное пространство её уставшей от окаменелых норм души начинает цвести и оживать, словно пустыня озеленилась."}),(0,i.jsx)(s.p,{children:"Пожалуй, только в экспедициях Релестия хотя бы ненадолго переставала беспрерывно мыслить мир через силу, подчинение и бесконечную иерархию. Вдали от духоты Коллегии, вечной гонки за знаниями, статусом и необходимостью постоянно соответствовать чужим ожиданиям куда большее значение приобретали выдержка, хладнокровие и способность не сломаться перед лицом очередной магической дряни, готовой сожрать грешника целиком. И именно там она временами встречала людей, которых не хотелось ни подавлять, ни опасаться, ни выслуживаться перед ними, — людей, которых Релестия действительно признавала равными себе. Рядом с ними её вечная настороженность ослабевала: она становилась спокойнее, говорила свободнее и впервые за долгое время чувствовала себя удивительно легко."}),(0,i.jsx)(s.p,{children:"Нельзя сказать, что Релестия чистоплюйка до мозга костей: в таком случае её бы не было в экспедициях, в которых волей-неволей, а приходится месить сапогами говно под ногами. Но тенденция, почти что болезненная склонность вычищать и выдраивать до блеска своё жизненное пространство, а особенно в те моменты, когда мозг устал от интеллектуальной деятельности, — этого было у неё не отнять. В этом и заключалось к тому же что-то от бюрократической педантичности: каждый листик к нужному акту, каждый карандаш на своё законное место, и в её понимании не было места фразе «гений властвует над хаосом». Ещё давно, будучи монастырской служащей, она пришла к выводу, наблюдая за счастьем собранных и аккуратных и горем несобранных и безалаберных, что «порядок — половина жизни»."}),(0,i.jsx)(s.p,{children:"И хотя характер Релестии оставляет желать лучшего, в особенности — что вполне естественно проистекает из вышеописанного — по отношению к тем, кто ниже её по рангу, силе и прочему, всё-таки не стоит думать, что она настолько зубастая, что за каждую оплошность, за каждую мелочь накинется с буйством голодного динозавра — отнюдь: и хотя она видит каждую соринку в чужом глазу, Релестия скорее подберёт нужный момент, чтобы высказать всё, что думает, и преимущественно в тех случаях, когда ей не гарантируется при всех прочих равных нагоняй от начальства. В остальном она, конечно, крайне вежлива и учтива, и хотя её характер допускает колкости, язвительность, насмешки, она всё-таки способна держать себя в руках даже в крайней степени раздражения."}),(0,i.jsx)(s.p,{children:"В отличие от собственной мягкости, мечтательности и прочих «неуместных» проявлений чувствительности, к своей похоти Релестия относится куда снисходительнее. Более того — временами именно в ней она находила едва ли не единственный простой и понятный способ ненадолго заглушить бесконечную внутреннюю усталость, накопившееся раздражение и тянущееся за ними уныние. Её по-прежнему тянуло преимущественно к людям сильным, уверенным и опасным, однако в подобном влечении она уже не видела чего-то постыдного: напротив, ей нравилось это ощущение чужой силы рядом, нравилось на короткое время позволять себе меньше думать, меньше контролировать собственные мысли и просто растворяться в чужом присутствии, будто сбрасывая с плеч неподъёмную тяжесть бесконечного «надо»."}),(0,i.jsx)(s.p,{children:"И, быть может, именно поэтому Релестия вновь и вновь возвращалась туда, где мир становился проще, честнее и опаснее; и, быть может, именно поэтому её так тянуло к людям, способным одним своим присутствием разжечь в ней огонь."}),(0,i.jsx)(s.p,{children:"И хотя можно частично утверждать о бессердечности Релестии, нельзя отрицать, что эта грешница не лишена благородных черт характера, одной из которых является искренняя благодарность, а вместе с благодарностью — своеобразные верность, доверие и сочувствие; к людям, которые к ней действительно были добры, которые ей помогали, когда ей было тяжело и до невозможности плохо, — она относится с благодарностью, ценит их и любит, хоть и крайне специфической любовью. Её любви вообще сложно заслужить, но два человека это безусловно сумели: Сейта, её коллега и хорошая подруга, а также наставник Релестии — Рейес."})]})}),(0,i.jsx)(r,{title:"Страхи",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Пустота",children:(0,i.jsx)(s.p,{children:"Глубокая внутренняя пустота, которую Релестия пытается заполнить знаниями, похотью, действиями — но не может. Она боится, что эта пустота останется с ней навсегда, и что за внешней оболочкой ничего не останется."})}),(0,i.jsx)(h,{title:"Потеря Рейеса и Сейты",children:(0,i.jsx)(s.p,{children:"Релестия очень сильно привязана к Рейесу и Сейте и совершенно не скрывает своих чувств к ним. Она искренне переживает за них и тяжело переносит любые угрозы их жизни или благополучию. Потеря Рейеса или Сейты стала бы для неё тяжёлым ударом и могла бы надолго выбить из колеи — слишком многое в её жизни связано с этими двумя."})}),(0,i.jsx)(h,{title:"Одиночество",children:(0,i.jsx)(s.p,{children:"Как бы Релестии ни хотелось самой себе в этом признаваться, ей гораздо легче существовать не на самой вершине, а рядом с ней — быть частью отлаженной системы, чьей-то исполнительницей, советницей или правой рукой, не неся на себе всю полноту ответственности за происходящее. Ей необходимы общество, структура и ощущение собственной принадлежности к чему-то большему. Длительная изоляция, отсутствие общества и ощущение, что ей не на кого опереться, быстро вгоняют её в тревогу, апатию и страх остаться совершенно одной."})}),(0,i.jsx)(h,{title:"Разочаровать наставника",children:(0,i.jsx)(s.p,{children:"Чувство стыда перед самой теоретической возможностью разочаровать своего наставника, Рейеса, заставляет Релестию выполнять то, что ей положено, даже когда она этого не хочет."})}),(0,i.jsx)(h,{title:"Потеря контроля",children:(0,i.jsx)(s.p,{children:"Страх перед собственной зависимостью от сиропа Гатиса и перед тем, что она может утратить контроль над своими действиями и эмоциями. Апатия и приступы ничего-не-делания пугают её саму."})})]})}),(0,i.jsx)(r,{title:"Мечты, цели",children:(0,i.jsxs)(j,{children:[(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Контроль погоды."})," Заветная мечта, святой Грааль. Релестия занимается климатогностикой именно потому, что хочет научиться управлять погодой. Она точно достигнет этого. Когда-нибудь…"]}),(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Познание Третьего мира."})," Релестия хочет приблизиться к Третьему миру настолько, насколько вообще способен приблизиться к нему грешник. Её пытливый ум жаждет знаний, и она готова идти на риск."]}),(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Экспедиции."})," Именно в экспедициях Релестия чувствует себя по-настоящему живой. Опасные и необычные места, где можно умереть, — это то, что возвращает её в детство, в ту беззаботную мечтательность, которой она обладает и сейчас."]}),(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Подняться по иерархии."})," Несмотря на усталость от системы, Релестия продолжает карабкаться вверх — потому что только так можно достичь большего. Она хочет быть сильной и могущественной, чтобы иметь право распоряжаться собственной жизнью."]})]})}),(0,i.jsx)(r,{title:"Биография (при жизни)",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(s.p,{children:"Релестия Люксевиар, урождённая Анна Мария фон Вернау, родилась 20 мая 1605 года в семье старого швабского рыцарства. Несмотря на то, что происхождение рода фон Вернау восходило к исторической Швабии, к началу XVII века данная ветвь семьи уже долгое время проживала на землях между Штутгартом и Эсслингеном, сохраняя при этом устойчивые связи с католической средой южногерманских и австрийских территорий. Семья принадлежала к числу представителей мелкого рыцарского дворянства, переживавшего к этому периоду постепенный экономический упадок. Причинами ухудшения материального положения стали многолетнее дробление наследственных владений между различными ветвями рода, накопившиеся долговые обязательства, а также общее ослабление значения старого рыцарского сословия в политической и хозяйственной системах Священной Римской империи. К началу Тридцатилетней войны семья фон Вернау сохраняла дворянский статус, родовую память и ограниченные земельные владения, однако уже не располагала прежними финансовыми возможностями."}),(0,i.jsx)(s.p,{children:"Анна Мария была третьей дочерью в семье, что существенно влияло на её дальнейшие жизненные перспективы. Для небогатого дворянства юго-западной Германии обеспечение нескольких дочерей полноценным приданым представляло серьёзную финансовую проблему. Дополнительное значение имела и конфессиональная обстановка региона. Штутгарт и значительная часть Вюртемберга после Реформации находились преимущественно под влиянием протестантизма, тогда как семья фон Вернау сохраняла приверженность католицизму и поддерживала связи с баварскими и австрийскими единоверцами. На фоне усиливающегося религиозного напряжения и нарастающей политической нестабильности родители Анны Марии приняли решение заранее определить её будущее, отдав дочь на воспитание в католический женский монастырь."}),(0,i.jsx)(s.p,{children:"Незадолго до начала Тридцатилетней войны Анна Мария была направлена в женскую монастырскую обитель на территории Баварии, предназначенную преимущественно для представительниц дворянских семей. Подобные монастыри в южногерманских землях XVII века выполняли не только религиозную, но и социально-воспитательную функцию, предоставляя дочерям аристократии образование и относительно стабильное положение в условиях нарастающего общественного кризиса. Воспитанницы обучались чтению и письму, основам латинского языка, церковному пению, рукоделию, ведению хозяйства и нормам поведения, соответствующим их происхождению. К моменту поступления в монастырь Анна Мария уже обладала базовым домашним образованием и была знакома с основами дворянского этикета, однако именно монастырское воспитание должно было завершить её подготовку к дальнейшей жизни в условиях общества раннего Нового времени."}),(0,i.jsx)(s.p,{children:"Несмотря на принадлежность монастыря к католической традиции, его внутренняя дисциплина во многом определялась личностью настоятельницы — женщины строгой, образованной и склонной к достаточно своеобразным взглядам для своего времени. Сохраняя жёсткий порядок в вопросах богослужения, распорядка и воспитания послушниц, она вместе с тем допускала отдельные послабления, прежде всего в отношении воспитанниц дворянского происхождения. Одним из таких исключений было право сохранить мирское имя после вступления в обитель. Поскольку большинство девушек уже носили традиционные католические имена, настоятельница считала принудительное наречение скорее внешним символическим актом, нежели подлинным проявлением духовного преображения. В результате Анна Мария фон Вернау, в отличие от части других сестёр, продолжила использовать своё мирское имя и в стенах монастыря."}),(0,i.jsx)(s.p,{children:"Период пребывания Анны Марии в обители совпал с началом Тридцатилетней войны, что постепенно изменило как повседневную жизнь монастыря, так и её собственное внутреннее состояние. Южногерманские монастыри, даже находившиеся вдали от крупных полей сражений, регулярно сталкивались с прохождением военных отрядов, перемещением наёмников, беженцев и обозов. Военная действительность всё чаще вторгалась в прежде замкнутое пространство монастырской жизни. Среди проходивших через баварские земли солдат нередко встречались наёмники различных германских княжеств — люди грубые, но зачастую производившие сильное впечатление своим внешним видом, манерами и ощущением принадлежности к иному, более свободному и опасному миру. Для молодой женщины, оказавшейся в условиях постоянной изоляции, подобные столкновения с внешней реальностью становились источником тяжёлого внутреннего смятения."}),(0,i.jsx)(s.p,{children:"В монастырских записях и духовных наставлениях того времени уныние и плотское искушение традиционно рассматривались как одни из наиболее опасных грехов для женских общин, и именно эти состояния постепенно начали проявляться в характере Анны Марии. Склонность к меланхолии, внутренней отчуждённости и продолжительным приступам подавленности сочеталась у неё с мучительным интересом к телесности и запретным мыслям, которые она воспринимала одновременно как искушение и как свидетельство собственной духовной испорченности. Строгий уклад монастырской жизни не устранял эти переживания, а, напротив, во многом усиливал их, превращая внутреннюю борьбу в постоянную часть её существования."}),(0,i.jsx)(s.p,{children:"Определённое влияние на формирование её мировоззрения оказала и семейная обстановка ранних лет. Отец Анны Марии, у которого проявлялись признаки нарастающего душевного расстройства, втайне от семьи (но не от своих дочерей) проявлял интерес к оккультным и мистическим сочинениям, которые пользовались ограниченным распространением среди части образованного дворянства и учёных кругов позднего Ренессанса. Речь шла преимущественно о трактатах по натуральной магии, алхимии, астрологии и религиозной мистике, официальное отношение к которым со стороны Церкви оставалось крайне настороженным. В детстве Анна Мария неоднократно сталкивалась с подобными книгами в отцовском кабинете, слышала его рассуждения о скрытых законах мироздания, божественных знамениях и присутствии сверхъестественного в человеческой жизни. Хотя значительную часть этих разговоров она тогда не понимала, пережитые впечатления оставили глубокий след в её сознании, способствуя развитию склонности к тревожным размышлениям, мистицизму и восприятию окружающего мира как пространства, в котором за привычной религиозной реальностью скрывается нечто более тёмное и непостижимое."}),(0,i.jsx)(s.p,{children:"Однако именно соприкосновение с запретными знаниями и полуоккультными представлениями, услышанными ещё в детстве, постепенно сформировало в Анне Марии внутренний конфликт, который с годами лишь обострялся. За внешней сдержанностью и монастырской дисциплиной скрывалась глубокая неудовлетворённость собственной жизнью. Её всё сильнее тяготили ощущения замкнутости и предопределённости собственного существования. Воспоминания о рассказах отца, о загадочных книгах, странных символах и идеях о скрытой природе мира пробуждали в ней не столько страх, сколько болезненное любопытство. Уже в юные годы Анна Мария всё чаще ловила себя на мысли, что в действительности жаждет не смиренной жизни в стенах монастыря, а познания, путешествий и соприкосновения с теми тайнами, о которых ей прежде доводилось лишь слышать. Внутренне она всё меньше воспринимала себя частью церковного мира, хотя продолжала добросовестно исполнять возложенные на неё обязанности."}),(0,i.jsx)(s.p,{children:"Наиболее близким человеком для неё стала Клара фон Райшах — послушница немного старше Анны Марии, происходившая из схожей среды южногерманского католического дворянства. Их семьи принадлежали к одному культурному и конфессиональному кругу, а детство обеих прошло в атмосфере религиозной тревожности, политической нестабильности и разговоров о мистике, знамениях и скрытых знаниях. По совпадению, родственники Клары также проявляли интерес к алхимическим и оккультным сочинениям, поэтому между двумя девушками довольно быстро возникло взаимопонимание, выходившее далеко за рамки обычной монастырской дружбы. Со временем именно Клара стала для Анны Марии единственным человеком, с которым она могла открыто обсуждать сомнения, страхи и мысли, считавшиеся опасными или еретическими."}),(0,i.jsx)(s.p,{children:"Внутри монастыря Анна Мария исполняла обязанности помощницы архивариуса и переписчицы. Благодаря хорошему образованию, аккуратному почерку и знанию латинского языка ей поручали ведение части внутренней документации, переписывание церковных текстов, сортировку писем и работу с монастырской библиотекой. Эта должность не относилась к числу высоких, однако считалась достаточно уважаемой и требовала усидчивости, грамотности и доверия со стороны старших сестёр. Именно работа с книгами и рукописями ещё сильнее подпитывала её интерес к запретным темам, поскольку среди старых текстов ей периодически попадались сочинения по мистике, натурфилософии и богословским спорам эпохи Реформации."}),(0,i.jsx)(s.p,{children:"Клара фон Райшах большую часть времени занималась монастырским лазаретом и аптекой. Она разбиралась в лекарственных травах, приготовлении настоек и уходе за больными, а также сопровождала старших сестёр во время помощи окрестным крестьянам и раненым путникам. Благодаря этому Клара чаще сталкивалась с внешним миром, слышала новости о ходе войны, движении войск и разорении соседних земель. Именно благодаря её рассказам Анна Мария всё острее ощущала, насколько стремительно рушится привычный порядок Священной Римской империи."}),(0,i.jsx)(s.p,{children:"К тридцатилетнему возрасту обеих женщин их внутренний кризис стало практически невозможно скрывать. Их разговоры, интерес к сомнительным сочинениям и всё более открытые высказывания о противоречиях внутри католического учения вызвали подозрения со стороны части монастырского руководства. В конечном итоге Анну Марию и Клару обвинили в распространении еретических взглядов и тайном отступничестве от церковных догматов. Окончательный приговор, однако, вынесен не был."}),(0,i.jsx)(s.p,{children:"На следующий день после начала разбирательства монастырь подвергся нападению блуждающего отряда мародёров. К этому моменту подобные банды уже представляли серьёзную угрозу для многих южногерманских земель. Нападавшие ворвались на территорию монастыря, разграбили хозяйственные постройки и подвергли насилию служительниц монастыря. В возникшем хаосе Анна Мария сумела укрыться на монастырской колокольне. Осознавая, что в случае пленения её ожидает та же участь, она предпочла покончить с собой, бросившись вниз с башни. Смерть наступила практически мгновенно."}),(0,i.jsx)(s.p,{children:"Обстоятельства гибели Анны Марии впоследствии сохранились лишь в разрозненных монастырских записях и поздних пересказах, часть которых со временем приобрела почти легендарный характер."})]})}),(0,i.jsx)(r,{title:"Жизнь в Энкраже",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(s.p,{children:"Пройдя испытание Башни, Анна Мария оказывается в Замке — и оккультная сторона сознания, та, что жаждала, не могла проспать ни одной ночи без потусторонних видений о чём-то далёком и неизвестном, загадочном, мистическом, — именно эта сторона сознания восторжествовала, потому что в действительности послушницы, священники, родственники и даже настоятельница монастыря — все ошибались, и только её отец, только он, кому она с детства почему-то верила, почему-то до упоения вслушивалась в его рассказы, — оказался прав. Но здесь, в месте, как она поняла, называемом Энкражем, всё было несколько иначе, чем рассказывал отец, и прямой параллели она провести не могла, но ведь сам факт!"}),(0,i.jsx)(s.p,{children:"Первым делом её пытливый ум, конечно, проник в библиотеку, но не только в неё — её скромность и вежливость всегда были ключом, позволяющим проникнуть в чужие души; её кротость, воспитанная тянущимися в вечность утренними и вечерними молитвами, ранними вставаниями, покорной службой и прочим, что было богоугодно в монастыре, — всё это, несмотря на её внутреннюю подавленность, на её внутреннюю пустоту, эту бездну, в которую она бросала новоприобретённые знания, похотливые мысли, спорадические действия, — бросала всё, что можно, лишь бы заполнить эту пустоту, — и не могла, не могла заполнить её, — всё это позволяло с вящей лёгкостью узнавать как можно больше об Энкраже в кратчайшие сроки."}),(0,i.jsx)(s.p,{children:"И хотя пустота разрослась внутри неё именно в монастыре, монастырь дал ей образование, выучку держаться, понимание того, что слово — это меч, разящий сердца. Жаль только — и об этом больше всего сожалела бы настоятельница, ещё тогда, покрасневшая от стыда, разочарования и обиды, дивившаяся тому, как одна из её любимых послушниц могла сомневаться, — именно она, настоятельница, сильнее всех прочих разочаровалась бы в том, что Анна Мария так превратно истолковала силу слова."}),(0,i.jsx)(s.p,{children:"И, как и говорилось, её пытливый ум проник не только в библиотеку, но и в души многих и многих — через слово, через сладостные вежливость и учтивость, через манеры, хотя и оттенённые её светским детством, но всё же в первую очередь какие-то монастырские, с запахом воска и благовоний. Но не тому учила её настоятельница, и всё же именно пустота и страх перед этой пустотой вынуждали её лгать, любезничать и лебезить, словно сам Сатана поселился на её языке, — лишь бы разузнать побольше, лишь бы пустота не требовала новых и новых жертв. И всё же это ей всегда удавалось: общаясь, она понимала, что именно от этого грешника узнаёт что-то новое, добьётся чего-то необходимого — и узнавала, и добивалась. Но больше всего она дивилась тому, в кого перевоплотилась сама, а также тому, в кого перевоплощались остальные, — хотя, что вполне ясно, первоочерёдно именно собственному перевоплощению."}),(0,i.jsx)(s.p,{children:"Некие оммёдзи, и у них было общество; и, ясное дело, она, росшая сначала среди обедневших дворян, а потом — в стенах монастыря, хотя, глядя на проходящих мимо наёмников, и воображала с каким-то романтическим трепетом тяготы, невзгоды, но вместе с тем и очарование свободной человеческой жизни, — всё же по-прежнему ощущала, как стены монастыря сдавливают ей мозг. Ей трудно было даже помыслить собственное существование вне пределов общества, вне упорядоченной системы, где у каждого было своё место и где существовала дедовщина: она помнила, какие наказания следовали за непослушание, как старшие подавляли младших, что делала война со слабыми, — и всё же без рамок чьего-то общества она чувствовала себя обездоленной и не могла противиться собственным привычкам."}),(0,i.jsx)(s.p,{children:"В её голову то и дело закрадывались мысли, что, быть может, она всё-таки в Аду — ведь именно грех привёл её сюда, и Ад, — в этом плане она была свободна от домыслов, — может выглядеть и ощущаться совсем не так, как некоторые себе надумали. И, быть может, именно так, как она видит его сейчас, он и выглядит, и именно в нём она теперь пребывает — за уныние, за похоть, за нежелание в полной мере смириться: лишь внешне, напоказ, но не внутренне, по-настоящему."}),(0,i.jsx)(s.p,{children:"И всё же, сколько бы девушка ни пыталась убедить себя, что прежняя Анна Мария фон Вернау умерла там, у подножия монастырской колокольни, сбросив своё тело навстречу земной тверди, лишь бы не попасть в грязные лапы неотёсанной наёмничьей сволочи, — на деле же прошлое продолжало тянуться за ней длинной тенью. Быть может, именно поэтому она, присоединившись к обществу оммёдзи, сменила имя. Не в монастыре, где настоятельница из собственных убеждений позволила Анне Марии сохранить мирское имя как нечто незначительное, внешнее, а здесь — среди оммёдзи, среди чародеев, чьи жизни были посвящены не триединому Богу, но познанию, магии и Третьему миру. Новому Богу."}),(0,i.jsx)(s.p,{children:"Так Анна Мария фон Вернау стала Релестией Люксевиар, словно бы этим новым именем окончательно разрывая связь с католичеством, монастырём и всем тем миром, который когда-то пытался научить её безропотному смирению."}),(0,i.jsx)(s.p,{children:(0,i.jsx)(s.strong,{children:"ПРИНЯТИЕ"})}),(0,i.jsx)(s.p,{children:"Как и говорилось выше, Релестия сначала попала в Софене, несколько пооглядывалась, как обстоят дела в этом вечном городе, чем-то напоминающем ей Рим — во всяком случае, исходя из тех отцовско-монастырских книжных рухлядей, чьи ветхие, рассыпающиеся страницы она во мраке едва ли светящей свечи читала в разные периоды своей жизни, — древнепахнущий и притягательный своей пока ещё неизученностью. Но неизученность не могла оставаться таковой бесконечно, и потому Релестия намертво намерилась стать частью этого общества: ей уже сказали, хотя, быть может, говорящий вообще не это имел в виду, подразумевал под сказанным нечто совершенно иное, но так уж сложилось, что именно следующим образом Релестия истолковала сказанное ей, — что выбор у неё, в общем-то, невелик, и её выточенный в иерархии мозг пришёл к однозначному для него выводу, что надо держаться своих и у своих же подниматься ввысь. Тем более что ни бедствующее дворянство, ни монастырь не смогли предложить в своё время более манящих карьерных видов."}),(0,i.jsx)(s.p,{children:"Она принесла клятву перед Палатой Магистериума и заключила договор с Ауспиком, таким образом официально и в какой-то степени торжественно на следующие долгие двадцать лет став «искателем» — в принципе, вновь оказавшись на той должности, иерархической ступеньке, своеобразной позиции во вселенной, которую она занимала по своему попаданию в монастырь: «принеси, подай, иди нахуй, не мешай». Девочка на побегушках. Благо, что грешники, как ей объяснили ещё в Замке, живут очень долго…"}),(0,i.jsx)(s.p,{children:(0,i.jsx)(s.strong,{children:"ИСКАТЕЛЬНИЦА"})}),(0,i.jsx)(s.p,{children:"И жизнь искательницы, несмотря на романтические представления об изучении магии, оказалась вовсе не жизнью избранной чародейки, а существованием прислужницы, ученицы и одновременно — пленницы Башни Тайн. Десятилетиями искатели мыли полы, переносили книги, переписывали документы, выполняли поручения старших и младших магов, ночами сидели над конспектами и трактатами, а днём вновь возвращались к работе. Релестия не то чтобы жаловалась. Более того — в каком-то болезненном смысле подобная жизнь казалась ей привычной. Стены Башни Тайн давили иначе, чем стены монастыря, но всё же давили; и всё-таки здесь ей впервые позволяли изучать то, о чём прежде она могла лишь украдкой читать в монастырских книгах. Буквы смешивались друг с другом, задания следовали друг за другом, одно поручение сменяло иное, и весь этот вихрь из дел, задач, исканий — он так закружился, так завертелся, что Релестия вскоре и вовсе перестала замечать, как быстро летят года и как меняется она сама."}),(0,i.jsx)(s.p,{children:"В самом начале своего магического пути она выбрала путь воды. Как спокойная, так и бурляще-шумящая, как умиротворяющая, словно горный водопад, так и разрушительная, подобно сокрушающему цивилизации цунами, — магия воды приходилась ей больше всего по душе: она давала постоять за себя, давала творчество, давала что-то текучее, изменчивое, приспособленческое. Очень подходящее естество для Релестии. Адаптивность — залог выживания. Вода, говорят, была ещё при сотворении мира. Она никогда не исчезнет."}),(0,i.jsx)(s.p,{children:"Училась Релестия с почти нездоровым усердием."}),(0,i.jsx)(s.p,{children:"Многие искатели ломались под тяжестью педагогических мер Магистериума, но Релестия, напротив, будто бы всё глубже врастала в него. Возможно, именно эта методика выбивала из неё так присущую многим оммёдзи лень — да, ей хотелось зарыться в мечты, в навязчивые грёзы, где она уже овладела и могущественной магией, и исследует дальние-дальние горизонты, и вообще всё хорошо, прекрасная маркиза, — но реальность быстро возвращала её с небес на землю, давала педагогически необходимый пинок под зад, и приступ лени сходил на нет. И хотя временами ей казалось, что она вновь оказалась в монастыре — среди бесконечной зубрёжки, иерархии и необходимости беспрерывно соответствовать чужим ожиданиям, — теперь у этого существования были цельность и целесообразность. Она действительно хотела знать. Хотела понимать. Хотела приблизиться к Третьему миру настолько, насколько вообще способен приблизиться к нему грешник."}),(0,i.jsx)(s.p,{children:"И всё же ни знания, ни магия не избавили её в полной мере от уныния. Да и как иначе, если это бич всех оммёдзи? Уныние продолжало преследовать её и в Энкраже: тихое, вязкое, тянущееся за ней чувство внутренней пустоты, будто бы сама душа её так и не сумела обрести покой ни после смерти, ни после перерождения. Не исчезла и похоть — напротив, среди оммёдзи, где знание и вместе с ним прилагающаяся «сила» почти обожествлялись, это чувство лишь сильнее сплеталось в её сознании с восхищением, страхом и преклонением перед могуществом. Её всё так же тянуло к опасным, уверенным в себе фигурам, к тем, кто обладал властью над окружающими и будто бы одним своим присутствием заставлял пространство вокруг становиться тяжелее."}),(0,i.jsx)(s.p,{children:"Одной из таких фигур стал Рейес Кабальеро де Морган — человек и пароход. Первое время Релестия меняла наставников, если уместно вообще в таком тоне говорить о «наставниках», как перчатки — либо никто не был ей в полной мере по душе, либо же она хотела понахвататься знаний с разных яблонь и вишень, а не ограничиваться одним жалким деревцем: зачем один сучок, когда есть целый сад? Но всё решилось в рамках нескольких спонтанных, мимолётных, но очень инспирирующих встреч. На тот период Рейес был младшим магом, членом круга Освобождения, а также ревностным апологетом потока духа. И, какое совпадение, именно круг Освобождения, как оказалось, заведовал различными экспедициями — тем самым, чего Релестии не хватало что в монастыре, что в Башне, и ей было трудно совладать с собственным сердцем: когда Рейес ей внезапно предложил поучаствовать в одной из вылазок, она, ни секунды не колеблясь, согласилась. Таким образом, изучение Третьего мира не поверхностно, а углублённо, в сочетании с захватывающими дух экспедициями под наставническим взором Рейеса определили карьерный путь Релестии: совсем скоро она стала поборницей круга своего учителя."}),(0,i.jsx)(s.p,{children:"Третьим и четвёртым потоками стали призыв и разум соответственно."}),(0,i.jsx)(s.p,{children:(0,i.jsx)(s.strong,{children:"ИСПЫТАНИЕ МАГИСТРОВ И РЕЛЕСТИЯ ЛЮКСЕВИАР, МЛАДШИЙ МАГ"})}),(0,i.jsx)(s.p,{children:"Спустя два стремительно пролетевших десятилетия обучения Релестия стояла перед вратами первого испытания магистров. Она его прошла. Но, как бы автору ни хотелось пользоваться этим несколько, скажем прямо, изъезженным оборотом речи, но ведь факт — в ней что-то изменилось. Она никому, даже своему главному наставнику, Рейесу, не рассказывала о том, что она там видела, что с ней происходило и что магистры с ней делали. Но после пройденного испытания былая, только зарождавшаяся лояльность Магистериуму стала практически беспрекословной (во всяком случае, со стороны) — и Релестия с гордостью стала носить звание младшего мага. В этот период она продолжила изучать новые потоки магии, а именно: тело и жизнь."}),(0,i.jsx)(s.p,{children:"Релестия присоединилась к кругу Освобождения уже на правах той, кто помогает проводить и организовывать экспедиции и привлекать туда новых искателей, — но не только привлекать, этого было бы мало, а действительно обучать их всем тонкостям, которые она самостоятельно сумела усвоить за прошедшие десятилетия. Но тут проявлялись особенности её характера: по отношению к подчинённым она была мстительной, злопамятной, жестокосердной фурией, не терпящей сюсюканий и прочей лабуды, мешающей процессу обучения новых потенциальных членов Магистериума. И всё больше укоренялась эта двойственность: кланяться вверх и давить вниз. Вместе с тем, с постепенным осознанием своего, пусть и на тот момент зачаточного, но могущества, в Релестии всё больше проклёвывался откровенный садизм: от психологического вплоть до физического, хотя последний ей редко удавалось проявить — но только потому, что она прекрасно понимала, насколько её положение всё ещё шаткое и что ей ещё необходимо очень многое доказать."}),(0,i.jsx)(s.p,{children:"Идеи прогрессистов казались ей наиболее близкими: Релестия искренне верила, что страх перед Третьим миром лишь сковывает Магистериум, а познание требует риска. Впрочем, в отличие от многих членов Круга, её мало интересовали политика и борьба за влияние внутри Палаты. Она почти не участвовала в интригах, редко выступала на собраниях и по возможности избегала вовлечения во внутренние конфликты Башни Тайн. Гораздо сильнее её привлекали исследования, экспедиции и работа с магией. Но, конечно, подобное отлынивание от возложенных на неё обязанностей не оставалось без внимания Рейеса, а потому, чувствуя некий стыд перед самой теоретической возможностью разочаровать своего наставника, Релестия всё-таки выполняла то, что ей положено выполнять. И чем больше она брала на себя, тем сильнее нарастала апатия — и не просто апатия, а настоящие приступы ничего-не-делания, нежелания существовать и, напротив, зудящего желания, быть может, вырваться в дикую природу, подальше от цивилизации, и ей приходилось себя всё сильнее перебарывать. Она стала использовать стимулирующие психику ресурсы Энкража."}),(0,i.jsx)(s.p,{children:"Со временем, однако, она вдоволь наупражнялась в прямом ущемлении искателей и пришла к выводу (во многом благодаря наставлениям Рейеса), что стоит несколько скорректировать свои методы. Она стала проявлять вежливость и учтивость даже по отношению к нижестоящим, чтобы расположить их к себе, привлечь туда, куда ей надо, и для того, что ей надо, — и только потом, во время экспедиций, или наедине, или просто в удобоваримый, по её мнению, момент, она изливала свою истинную суть. В этом смысле она стала гораздо более изощрённой."}),(0,i.jsx)(s.p,{children:"Одним из наиболее примечательных моментов её биографии на позиции младшего мага стало участие в нападении на дворец золотых драконов в 1730 году. Релестии, которой была близка идея подчинения магии и полного овладения ею, претила сама мысль о том, что какие-то потешные вымирающие ящерицы распоряжаются могущественными магическими сферами. Поэтому, когда ей улыбнулась возможность поучаствовать в их истреблении и принудительном изъятии сфер на благо общества оммёдзи, она ни секунды не колебалась."}),(0,i.jsx)(s.p,{children:"Вторым примечательным моментом стало знакомство с Сейтой — та уже была на момент знакомства вальгардкой, младшим магом, с определёнными, хоть и далёкими от понимания Релестии, социальными трудностями, неувязками, — и если есть топографический кретинизм, то Релестия в своей голове обозвала проблему Сейты кретинизмом социальной направленности. Сложно было уловить, как человек не понимает совершенного очевидного: допустим, как не понять, что нельзя сесть на третий стул справа во время пира по отношению к тому, кто этот пир устроил? Тогда в глазах окружающих ты никто иной, как чёрт. И ты что, самый умный, что ли, — всех здесь своим неуместным, беспардонным, возмутительным поступком оскорбил и думаешь, что тебе за это совершенно ничего не будет? Для Релестии такие вещи были как два плюс два: их нельзя не знать, а если не знаешь, то, быть может, с тобой реально что-то не так? Но Сейта ведь тоже ходила под Рейесом. Значит, она не такой простой орешек, как могло показаться со стороны. Поэтому фрау Люксевиар несколько поубавила снисходительно-удивлённый тон и решила познакомиться с «дикаркой» поближе. Релестия прониклась к Сейте то ли сочувствием, то ли пониманием: положение Сейты было не менее шатким, чем её собственное. Возможно, под единоначалием Рейеса им действительно стоило держаться вместе — всё-таки общего между ними было не намного меньше, чем различий. В самой первой экспедиции, куда Релестия пригласила Сейту — с одной стороны, как вальгардку, с другой — как подругу по несчастью, — они сблизились ещё сильнее. Если Релестия стала в их тандеме светочем цивилизации, способствующим социализации Сейты, то Сейта, в свою очередь, раскрыла подруге глаза на гораздо более дикие и необузданные материи. А дальнейшие экспедиции, совместные служения и обучение лишь укрепили их отношения, сделав их по-настоящему тёплыми и близкими."}),(0,i.jsx)(s.p,{children:"Также стоит упомянуть, что именно в этот период Релестия благодаря помощи одного из своих сикигами стала заниматься «климатогностикой». Поспособствовало этому и нападение на дворец золотых драконов: в ходе подготовки к нападению, самого нападения и изучения его результатов она разузнала, что драконы — именно благодаря драгоценным сферам — способны напрямую воздействовать на проклятую энергию, придавая ей необходимые свойства. С помощью сикигами оммёдзи тоже способны на подобное, но не без трудностей, и это — непаханое поле, которое Релестии ещё предстоит освоить."}),(0,i.jsx)(s.p,{children:"Сейчас ей гораздо легче с помощью сикигами заниматься прогнозами, наблюдением и изучением. Но контроль погоды… заветная мечта, святой Грааль. Она точно достигнет этого. Когда-нибудь…"}),(0,i.jsx)(s.p,{children:"Изначально Релестия практиковала данную дисциплину преимущественно самостоятельно либо при участии небольшого круга «коллег» из числа оммёдзи. Позднее исследования продолжились уже в более тесном и системном сотрудничестве с НАЭ на правах синклита. Климатогностика представляет собой дисциплину, изучающую потоки проклятой энергии в пределах бастионных зон, а также, несмотря на сопутствующие сложности, за их пределами. Основное внимание в рамках исследований уделяется влиянию этих потоков на климатические условия, атмосферные аномалии и различные катастрофические явления — от буранов, торнадо и землетрясений до феноменов, способных воздействовать на поведение грешников."}),(0,i.jsx)(s.p,{children:"Значительная часть получаемой информации остаётся внутри сообщества оммёдзи и структур НАЭ. Даже в рамках сотрудничества с НАЭ Релестия предпочитает раскрывать результаты исследований, наблюдений и открытий лишь частично, если существует возможность сохранить часть данных закрытой."}),(0,i.jsx)(s.p,{children:(0,i.jsx)(s.strong,{children:"ФИНАЛЬНОЕ ИСПЫТАНИЕ МАГИСТРОВ"})}),(0,i.jsx)(s.p,{children:"Затем, по предложению Рейеса, от которого невозможно было отказаться, Релестия прошла второе испытание Магистериума. О нём она тоже, как и о первом, напрямую ничего не говорила. Но по отдельным фразам можно было прийти к выводу, что ей пришлось призвать очень опасного демонического сикигами."}),(0,i.jsx)(s.p,{children:"С тех пор она стала старшим магом, правой рукой Рейеса и почётным членом Коллегии Старших магов. Ко всему прочему, именно после второго испытания Магистериума Релестия стала пользоваться гораздо большим количеством благ и послаблений со стороны общества оммёдзи, и даже их до сей поры крайне тёплые отношения с Рейесом со временем, хоть и не абсолютно, охладели — и не совсем ясно, только ли само испытание поспособствовало этому или что-то ещё…"}),(0,i.jsx)(s.p,{children:(0,i.jsx)(s.strong,{children:"ЗАМЕТКИ К БИОГРАФИИ"})}),(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsx)(s.li,{children:"Изучаемые потоки магии, будучи искательницей в хронологической последовательности: вода, дух, призыв, разум."}),"\n",(0,i.jsx)(s.li,{children:"Изучаемые потоки магии, будучи младшим магом в хронологической последовательности: тело и жизнь."}),"\n"]})]})})]}),(0,i.jsxs)(r,{title:"Дополнительно",children:[(0,i.jsx)(r,{title:"Факты о персонаже",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Булкохрустка",children:(0,i.jsx)(s.p,{children:"Релестия всегда была рьяной завсегдатайкой пекарен, булочных и прочих магазинчиков Софене, где можно купить и съесть что-нибудь сдобненькое: душистое, с семенами, с растениями, с изыском, со вкусом — в общем, выпечка ещё давным-давно запала ей в самое сердце, и хотя ест она больше не обжорства ради, а ради сиюминутных удовольствий, с подобным пристрастием приходится мириться всем, к кому она неровно дышит. Она испекает сама, интересуется новинками в мире выпечки и никогда не упустит возможность угостить грешника, услаждающего ей глаз, вкусным пирогом или маффином с необыкновенной начинкой."})}),(0,i.jsx)(h,{title:"Корпоративизм",children:(0,i.jsx)(s.p,{children:"Выглаженная форма, длинные, уходящие в бесконечность погоны, табельное оружие — говорят, полиция в современном виде зародилась в Лондоне, но любой служитель правопорядка, от древней клинописной Месопотамии до светящихся неоном вывесок Шанхая, знает, что блюсти закон было необходимо всегда и везде. Не являясь стражницей, Релестия тем не менее неровно дышит к государевым мужам: в прошлом ей уже приходилось напрягать свои связи, чтобы замять несколько неудобных разбирательств по превышению полномочий; за это её невзлюбили в палате магов. Но жалеть о своих поступках Релестия не жалеет и при любом удобном случае заявляет — во всяком случае в компании доверенных лиц, — что, вернись она в прошлое, поступила бы точно так же."})})]})}),(0,i.jsx)(r,{title:"Внешность",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(s.p,{children:"Внешне Релестия напоминает эффективную и беспощадную, возможно, с нотками неврастеничной стервозности менеджерку — безусловно, клиентоориентированную и в край вежливую. По ней сразу видно, какой она породы: искусственной, пудрящей мозги, неискренней. У неё аккуратные черты лица с плавными переходами, тяжёлый взгляд, как после тысячелетней запары, а также холодность и отстранённость в нём. Глаза красного цвета, как надречная калина. Волосы густые и прямые, до плеч, постриженные в симметричный тёмно-синий боб с зеленоватым отливом на свету. Чёлка почти полностью закрывает лоб, а общая парикмахерская конструкция на голове красиво обрамляет лицо. По ней видно, что она мнит себя римской патрицианкой и смотрит на всех с высоко приподнятым носом."}),(0,i.jsx)(s.p,{children:"При этом Релестия довольно улыбчива, что сильно контрастирует с её тяжёлым, часто прищуренным взглядом. Это, правда, не улыбка во все зубы, а скорее игривая полуулыбка, как бы невзначай намекающая: «Да-да, конечно, вы можете ко мне обратиться, я всегда к вашим услугам и с радостью отвечу на все ваши вопросы»."}),(0,i.jsx)(s.p,{children:"У Релестии немаленький рост — 175 сантиметров. Развитые плечи, выраженная талия, прямая осанка. Она нередко одевается не только в формально-церемониальные наряды, хотя их очень любит носить, — она твёрдо убеждена, что строгий крой сочетается с её фигурой и подчёркивает элитарную натуру, — но и в фешенебельные костюмы с эпатажем."})]})}),(0,i.jsx)(r,{title:"Навыки и умения",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Жрица мёртвой буквы закона и её коллеги",children:(0,i.jsx)(s.p,{children:"Когда четвёртое столетие подряд перекладываешь бумажки с места на место, волей-неволей обнаруживаешь, что начинаешь разговаривать с параграфами и спорить с буквами — ведь для чего нужны буквы, упорядоченные в слова, а слова, уложенные штабелями в книги, если не для того, чтобы регулировать хаос нашей с вами жизни? Релестия слишком долго коммуницировала с чиновниками Софене по долгу службы при магистре Рейесе. И не только с ними: корреспонденция, дипломатические визиты и прочие штуковины, неотвязно сопутствующие её жизни, заставили «чувствовать», что говорят братья по несчастью. Когда чиновник пытается сокрыть от неё правду за маловразумительными, но безусловно стройными речевыми конструкциями, она с вящей лёгкостью понимает, что «на самом деле» подразумевается. Она плавает в бюрократическом эзоповом языке как акула в воде, а потому ей легко даётся общение с чиновниками не только Софене, но и других рас: она в них, как и они в ней, распознаёт родную кровь, наполненную чёрными чернилами. Полунамёки, скрытые смыслы и «правду» она распознаёт согласно решениям ответственного за квест / эпизод гейм-мастера."})}),(0,i.jsx)(h,{title:"Верховая езда",children:(0,i.jsx)(s.p,{children:"Посредственный уровень."})}),(0,i.jsx)(h,{title:"Знание квеллария",children:(0,i.jsx)(s.p,{children:"Современный и средний квелларий — на пристойном уровне; освоение старого квеллария пока не увенчалось успехом. Также знает латынь."})}),(0,i.jsx)(h,{title:"Физподготовка и физкультура",children:(0,i.jsx)(s.p,{children:"Чтобы достойно выдерживать изнурительные экспедиции, поддерживать себя в форме, а также иметь возможность сливаться в симбиозе с сикигами, чья мощь преимущественно физическая, а не магическая, Релестия регулярно занимается силовыми и кардиотренировками. В её программу входят бег, упражнения на координацию, работа с гирями, калистеника и прочее."})}),(0,i.jsx)(h,{title:"Фигурное катание и конькобежный спорт",children:(0,i.jsx)(s.p,{children:"Релестия освоила обе дисциплины благодаря регулярным тренировкам и магической способности «Ледяные коньки», позволяющей ей кататься по льду без обычных коньков. Помимо спортивного применения, способность особенно эффективна в бою."})}),(0,i.jsx)(h,{title:"Знание общества оммёдзи",children:(0,i.jsx)(s.p,{children:"Релестия хорошо знакома с обычаями, этикетом, социальными нормами и негласными правилами общества оммёдзи. Она разбирается в его внутренних порядках, знает о секретах и особенностях различных политических кланов и понимает, как выстраиваются отношения между ними."})}),(0,i.jsx)(h,{title:"Знание климатических явлений Энкража",children:(0,i.jsx)(s.p,{children:"Релестия хорошо разбирается в климатических особенностях Энкража, в том числе в характерных для разных регионов погодных явлениях и их закономерностях."})})]})}),(0,i.jsx)(r,{title:"Слабости",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Головные боли, чёрт бы их побрал!",children:(0,i.jsx)(s.p,{children:"Она страдает от мигренозных головных болей, которые появляются с особой интенсивностью после чрезмерного напряжения цепей. Допустим, если Релестия поучаствовала в особенно напряжённом бою, применяя свои магические способности одну за другой, с огромным шансом (по решению гейм-мастера) она получает продолжительную головную боль. Природа данных болей не до конца изучена, и, хотя Релестия работает над этим, прийти к окончательному пониманию того, что лежит в их основе, ей не удалось. Подобные боли способны возникать и спорадически. А ещё чаще они возникают, когда меняются потоки проклятой энергии и погода резко ухудшается. Точное воздействие на Релестию в конкретный момент определяется гейм-мастером, но закономерны слезоточивость, дезориентация, светобоязнь, чувствительность к запахам и т. д."})}),(0,i.jsxs)(h,{title:"На игле",children:[(0,i.jsx)(s.p,{children:"Релестия всегда старалась соответствовать лучшим соответствиям, но поди ж ты, если одни рождаются с исключительным трудолюбием в крови, то она — нет; а трудиться надо, а достигать высот хочется, поэтому Релестия постепенно подсела на стимуляторы. Для этого она использует сироп Гатиса — сок спелых плодов, уваренный с Златоцветом, дающий мощный заряд чистой энергии, ясность ума и успокоение. Релестия всегда носит с собой небольшую флягу с сиропом, чтобы в любой момент вернуть себе силы и вновь взяться за работу."}),(0,i.jsx)(s.p,{children:"Но, конечно, зависимость есть зависимость. Она нередко перебарщивает с дозировкой, что приводит к гиперактивности и бессоннице, а после — к тяжёлым откатам, когда ей трудно пошевелить и пальцем, а жизнь кажется ещё более вялой и тщетной, чем обычно. Будучи дитём уныния, она и тоскует, и в апатии бывает, и тщетность бытия ей до боли знакома — но без очередной дозы Гатиса всё это становится ещё невыносимее. Помогающий решить проблему в краткосрочной перспективе, сироп на длинной дистанции лишь сильнее истощает и без того уставшую душу — но избавиться от зависимости она не может."})]}),(0,i.jsx)(h,{title:"Апатия",children:(0,i.jsx)(s.p,{children:"Временами Релестия впадает в состояние глубокой апатии, когда теряет всякий интерес к жизни, работе и происходящему вокруг. В такие моменты даже привычные для неё цели и обязанности кажутся бессмысленными, а сама жизнь — лишённой какой-либо ценности. Релестия употребляет различные стимуляторы, однако именно Гатис со временем стал её естественным помощником в подобных состояниях: он быстро возвращает ей энергию, ясность мысли и хотя бы временный интерес к происходящему. Вывести её из апатии также способны сильное потрясение, необычное событие или ситуация, способная вновь пробудить в ней интерес к жизни. Без этого Релестия может надолго замыкаться в себе и практически переставать что-либо предпринимать."})}),(0,i.jsx)(h,{title:"Непереносимость одиночества",children:(0,i.jsx)(s.p,{children:"Как бы Релестии ни хотелось самой себе в этом признаваться, ей гораздо легче существовать не на самой вершине, а рядом с ней — быть частью отлаженной системы, чьей-то исполнительницей, советницей или правой рукой, не неся на себе всю полноту ответственности за происходящее. Ей необходимы общество, структура и ощущение собственной принадлежности к чему-то большему. Поэтому даже в экспедициях, где она может оказаться вдали от цивилизации на многие недели, Релестия никогда не стремится быть одна: рядом обязательно должны находиться люди, с которыми её связывает общее дело. Длительная же изоляция, отсутствие общества и ощущение, что ей не на кого опереться, быстро вгоняют её в тревогу, апатию и страх остаться совершенно одной."})}),(0,i.jsx)(h,{title:"Привязанность",children:(0,i.jsx)(s.p,{children:"Релестия очень сильно привязана к Рейесу и Сейте и совершенно не скрывает своих чувств к ним. Она искренне переживает за них и тяжело переносит любые угрозы их жизни или благополучию. Особенно сложны для неё отношения с Рейесом: за последнее время они заметно охладели, а их взгляды на многие вопросы всё чаще расходятся, однако Релестия по-прежнему не хочет разрывать эту связь и едва ли способна представить, что однажды ей придётся пойти против собственного наставника. Потеря Рейеса или Сейты стала бы для неё тяжёлым ударом и могла бы надолго выбить из колеи — слишком многое в её жизни связано с этими двумя."})})]})}),(0,i.jsx)(r,{title:"Связанные персонажи",children:(0,i.jsx)(d,{children:(0,i.jsx)(h,{title:"Клара фон Райшах",children:(0,i.jsx)(s.p,{children:"Послушница монастыря и по совместительству лучшая подруга Релестии ещё тогда, на Земле, в монастыре. Связующим предметом является Новый Завет на латыни."})})})})]}),(0,i.jsx)(x,{children:(0,i.jsx)(s.p,{children:"Я очень, безумно люблю новых искателей — свежая кровь, новые лица! Приятно познакомиться с каждым и познакомить каждого с Магистериумом"})})]})}function n(e,i){throw Error("Expected "+(i?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}e.s(["default",0,function(e={}){let{wrapper:n}={...(0,l.useMDXComponents)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(s,{...e})}):s(e)}])}]);